-- Show the reference list (::: {#refs}) as "Books" and "Papers and other sources".
-- The list is generated by citeproc after all user filters have run, so this filter only
-- records each entry's type (@book, @article, ...) from the bibliography and adds a small
-- script that regroups the entries in the browser.
local function bib_types(meta)
  local types = {}
  local bibs = meta.bibliography
  if not bibs then return types end
  if pandoc.utils.type(bibs) ~= 'List' then bibs = { bibs } end
  for _, b in ipairs(bibs) do
    local path = pandoc.utils.stringify(b)
    local fh = io.open(path, 'r') or io.open(pandoc.path.join({ quarto.project.directory, path }), 'r')
    if fh then
      for kind, key in fh:read('a'):gmatch('@(%a+)%s*{%s*([^,%s]+)%s*,') do
        types[key] = kind:lower()
      end
      fh:close()
    end
  end
  return types
end

function Pandoc(doc)
  if not quarto.doc.is_format('html') then return nil end
  local types = bib_types(doc.meta)
  local found = false
  doc = doc:walk({ Div = function(el) if el.identifier == 'refs' then found = true end end })
  if not found then return nil end
  local script = [[
<script>
document.addEventListener('DOMContentLoaded', function () {
  var types = ]] .. quarto.json.encode(types) .. [[;
  var refs = document.getElementById('refs');
  if (!refs) return;
  var entries = Array.prototype.slice.call(refs.querySelectorAll(':scope > .csl-entry'));
  var books = entries.filter(function (e) { return types[e.id.replace(/^ref-/, '')] === 'book'; });
  var others = entries.filter(function (e) { return books.indexOf(e) < 0; });
  if (!books.length || !others.length) return;
  function heading(text, id) {
    var h = document.createElement('h3'); h.textContent = text; h.id = id; h.className = 'refs-group';
    return h;
  }
  refs.appendChild(heading('Books', 'refs-books'));
  books.forEach(function (e) { refs.appendChild(e); });
  refs.appendChild(heading('Papers and other sources', 'refs-papers'));
  others.forEach(function (e) { refs.appendChild(e); });
});
</script>]]
  doc.blocks:insert(pandoc.RawBlock('html', script))
  return doc
end
